function updateLocalTime(){const e=new Date;document.getElementById("currentLocalTime").innerText=`Your local time: ${e.toLocaleTimeString()}`}document.getElementById("submit-location").addEventListener("click",(function(){const e=document.getElementById("location").value.trim(),t=document.getElementById("apikey").value.trim();if(!e||!t)return void alert("Please provide a valid location and API key.");const[n,o]=e.split(",").map((e=>e.trim()));fetch(`https://api.openweathermap.org/data/2.5/weather?q=${n},${o}&appid=${t}`).then((e=>e.json())).then((e=>{if(200!==e.cod)return void alert(`Failed to retrieve weather data: ${e.message}`);const t=1e3*e.timezone,n=new Date;let o=new Date(n.getTime()+t);const i=new Date,r=new Date(i.getFullYear(),0,1).getTimezoneOffset();i.getTimezoneOffset()<r&&o.setHours(o.getHours()-1);const s=(3600*o.getHours()+60*o.getMinutes()+o.getSeconds())/86400;document.getElementById("localTime").innerText=`Local time: ${o.toLocaleTimeString()}`;const a=document.getElementById("sun-path"),m=a.getTotalLength(),u=s*m,c=a.getPointAtLength(u),d=document.getElementById("sun-glow");d.setAttribute("cx",c.x),d.setAttribute("cy",c.y);const l=1e3*e.sys.sunrise+t,g=1e3*e.sys.sunset+t,y=new Date(l),T=new Date(g);let h=(3600*y.getHours()+60*y.getMinutes()+y.getSeconds())/86400*m,E=(3600*T.getHours()+60*T.getMinutes()+T.getSeconds())/86400*m;const I=a.getPointAtLength(h),B=a.getPointAtLength(E);document.getElementById("sunrisemarker").setAttribute("cx",I.x),document.getElementById("sunrisemarker").setAttribute("cy",I.y),document.getElementById("sunsetmarker").setAttribute("cx",B.x),document.getElementById("sunsetmarker").setAttribute("cy",B.y);const p=y.toLocaleTimeString(),x=T.toLocaleTimeString();let L=(T-y)/36e5;L=L.toFixed(2),document.getElementById("sunriseTime").innerText=`Sunrise: ${p}`,document.getElementById("sunsetTime").innerText=`Sunset: ${x}`,document.getElementById("daylightHours").innerText=`Total daylight hours: ${L}`,(o<y||o>T)&&(document.getElementById("sunriseTime").innerText=`Sunrise: ${x}`,document.getElementById("sunsetTime").innerText=`Sunset: ${p}`)})).catch((e=>{console.error("Error fetching weather data:",e),alert("Failed to retrieve weather data.")}))})),setInterval(updateLocalTime,1e3),updateLocalTime();